        <button type="button" onClick={() => saveHuntDownload(huntUniqueRowsCsv(result, index), `hunt-query-${index + 1}-unique-retained-rows.csv`, 'text/csv;charset=utf-8')} className="min-h-9 rounded border border-surface-600 px-3 py-2 text-primary-300">Export all once-occurring retained rows CSV</button>
