        {uniqueMatches.slice((currentUniquePage - 1) * 10, currentUniquePage * 10).map(position => <div key={position} className="min-w-0 rounded border border-surface-700 p-3"><h4 className="text-surface-100">Full-row value at retained row {position}, occurs once</h4><button type="button" aria-label={`Inspect once-occurring retained row ${position} for query ${index + 1}`} onClick={() => setDetailRow(position)} className="mt-2 min-h-9 rounded border border-surface-600 px-3 py-2 text-primary-300">Inspect retained row {position}</button></div>)}
        {uniqueMatches.length > 10 && <div className="flex flex-wrap items-center gap-2"><button type="button" disabled={currentUniquePage === 1} onClick={() => setUniquePage(currentUniquePage - 1)} className="min-h-9 rounded border border-surface-600 px-3 py-2 text-surface-200 disabled:opacity-40">Previous once-occurring rows</button><span className="text-surface-400">Once-occurring page {currentUniquePage} of {uniquePages}</span><button type="button" disabled={currentUniquePage === uniquePages} onClick={() => setUniquePage(currentUniquePage + 1)} className="min-h-9 rounded border border-surface-600 px-3 py-2 text-surface-200 disabled:opacity-40">Next once-occurring rows</button></div>}
